// rawTopLevel decodes a config blob into its top-level keys WITHOUT touching
// any value bytes: json.Unmarshal into json.RawMessage preserves each value's
// exact source bytes, so byte-identity comparisons are meaningful.
func rawTopLevel(t *testing.T, config string) map[string]json.RawMessage {
	t.Helper()
	var cfg map[string]json.RawMessage
	if err := json.Unmarshal([]byte(config), &cfg); err != nil {
		t.Fatalf("parse config: %v", err)
	}
	return cfg
}

// rawSourceChain extracts the metadata_sources elements as raw byte slices
// (same RawMessage law: no compaction, no re-ordering).
func rawSourceChain(t *testing.T, config string) []json.RawMessage {
	t.Helper()
	var chain []json.RawMessage
	if err := json.Unmarshal(rawTopLevel(t, config)["metadata_sources"], &chain); err != nil {
		t.Fatalf("parse metadata_sources: %v", err)
	}
	return chain
}

// rowConfig reads one module row's raw config_json straight from the store.
func rowConfig(t *testing.T, r *Registry, moduleID string) string {
	t.Helper()
	var cfg string
	if err := r.s.DB().QueryRowContext(context.Background(),
		`SELECT config_json FROM modules WHERE id = ?`, moduleID).Scan(&cfg); err != nil {
		t.Fatalf("load %s row: %v", moduleID, err)
	}
	return cfg
}

// TestSetBindingOptionsRewritesOneBinding covers the tmdb-enrichment 3.1 write
// law: ONE guarded UPDATE rewrites ONLY the target binding's options inside the
// module row's config_json — schema_version and every sibling binding are
// byte-identical after the write — and the in-memory cache reads through byID
// immediately (no stale entry, no re-Open needed).
func TestSetBindingOptionsRewritesOneBinding(t *testing.T) {
	ctx := context.Background()
	r, s := openRegistry(t)

	const (
		moduleID = "tv" // tmdb sits mid-chain (priority 3) with non-empty seeded options
		pluginID = "tmdb"
	)
	before := rowConfig(t, r, moduleID)
	beforeTop := rawTopLevel(t, before)
	beforeChain := rawSourceChain(t, before)
	options := json.RawMessage(`{"api_key":"test-key","language":"ru-RU"}`)

	if err := r.SetBindingOptions(ctx, moduleID, pluginID, options); err != nil {
		t.Fatalf("SetBindingOptions(tv, tmdb): %v", err)
	}

	// The persisted row: every sibling region byte-identical, schema_version
	// unchanged, and ONLY the tmdb binding's options value replaced.
	after := rowConfig(t, r, moduleID)
	afterTop := rawTopLevel(t, after)
	afterChain := rawSourceChain(t, after)
	for _, key := range []string{"schema_version", "display", "scanner", "identity_fields"} {
		if !bytes.Equal(beforeTop[key], afterTop[key]) {
			t.Errorf("config %s region changed: before %s after %s", key, beforeTop[key], afterTop[key])
		}
	}
	if len(afterChain) != len(beforeChain) {
		t.Fatalf("metadata_sources len = %d, want %d (bindings never added or dropped)", len(afterChain), len(beforeChain))
	}
	for i, beforeElem := range beforeChain {
		var b, a map[string]json.RawMessage
		if err := json.Unmarshal(beforeElem, &b); err != nil {
			t.Fatalf("parse before element %d: %v", i, err)
		}
		if err := json.Unmarshal(afterChain[i], &a); err != nil {
			t.Fatalf("parse after element %d: %v", i, err)
		}
		var plugin string
		if err := json.Unmarshal(b["plugin_id"], &plugin); err != nil {
			t.Fatalf("parse element %d plugin_id: %v", i, err)
		}
		if plugin == pluginID {
			for key, want := range b {
				if key == "options" {
					continue // the ONE region the write may touch
				}
				if !bytes.Equal(want, a[key]) {
					t.Errorf("target binding %s.%s changed: before %s after %s", plugin, key, want, a[key])
				}
			}
			if !bytes.Equal(a["options"], options) {
				t.Errorf("target binding options = %s, want verbatim %s", a["options"], options)
			}
			continue
		}
		if !bytes.Equal(beforeElem, afterChain[i]) {
			t.Errorf("sibling binding %s rewritten byte-for-byte:\nbefore %s\nafter  %s", plugin, beforeElem, afterChain[i])
		}
	}

	// Read-through: the SAME Registry serves the new options from byID
	// immediately, with the rest of the parsed binding untouched.
	m, err := r.Get(moduleID)
	if err != nil {
		t.Fatalf("Get(tv) after write: %v", err)
	}
	if m.SchemaVersion != 2 {
		t.Errorf("SchemaVersion after write = %d, want 2 (options edits never bump the schema)", m.SchemaVersion)
	}
	var target *MetadataSourceBinding
	for i := range m.MetadataSources {
		if m.MetadataSources[i].PluginID == pluginID {
			target = &m.MetadataSources[i]
		} else if m.MetadataSources[i].Options == nil {
			t.Errorf("sibling %s options nil after write", m.MetadataSources[i].PluginID)
		}
	}
	if target == nil {
		t.Fatalf("tmdb binding missing from cache after write")
	}
	if !bytes.Equal(target.Options, options) {
		t.Errorf("cached options = %s, want verbatim %s", target.Options, options)
	}
	if target.Priority != 3 || !target.Enabled || target.AuthMode != "SERVER" {
		t.Errorf("cached binding = %+v, want priority 3 enabled SERVER (only options changed)", target)
	}

	// Roundtrip: a fresh Registry over the same store reads the new options
	// back (the write persisted, not just a cache mutation).
	r2, err := Open(ctx, s)
	if err != nil {
		t.Fatalf("re-Open: %v", err)
	}
	m2, err := r2.Get(moduleID)
	if err != nil {
		t.Fatalf("Get(tv) after re-Open: %v", err)
	}
	for _, src := range m2.MetadataSources {
		if src.PluginID == pluginID && !bytes.Equal(src.Options, options) {
			t.Errorf("re-opened options = %s, want verbatim %s", src.Options, options)
		}
	}
}

// TestSetBindingOptionsUnknownRefused covers the refusal pair: an unknown
// module id wraps errNotFound (the api maps 404) and a plugin the module does
// not bind as a metadata_source wraps errUnknownSource (the api maps 400) —
// including a plugin bound as the SCANNER slot, which is not a metadata source.
// Every refusal leaves the row byte-untouched.
func TestSetBindingOptionsUnknownRefused(t *testing.T) {
	ctx := context.Background()
	r, _ := openRegistry(t)

	options := json.RawMessage(`{"api_key":"x"}`)

	if err := r.SetBindingOptions(ctx, "does-not-exist", "tmdb", options); !errors.Is(err, errNotFound) {
		t.Errorf("unknown module err = %v, want errNotFound", err)
	}
	// serial binds serial-parser + frame-grabber + shikimori + tmdb (no
	// kinopoisk — that slot belongs to the tv chain).
	if err := r.SetBindingOptions(ctx, "serial", "kinopoisk", options); !errors.Is(err, errUnknownSource) {
		t.Errorf("unbound plugin err = %v, want errUnknownSource", err)
	}
	// base-scanner IS bound on tv — as the scanner slot, not a metadata source.
	if err := r.SetBindingOptions(ctx, "tv", "base-scanner", options); !errors.Is(err, errUnknownSource) {
		t.Errorf("scanner-slot plugin err = %v, want errUnknownSource", err)
	}
	// Malformed options are refused before any write (a splice of invalid JSON
	// would corrupt the config document).
	if err := r.SetBindingOptions(ctx, "tv", "tmdb", json.RawMessage(`{oops`)); err == nil {
		t.Errorf("invalid options accepted, want an error")
	}

	// Nothing written: the tv row is byte-identical to its seed.
	if got := rowConfig(t, r, "tv"); got != tvConfigJSON {
		t.Errorf("tv row changed after refusals (%d vs %d bytes)", len(got), len(tvConfigJSON))
	}
}

// TestRegistryConcurrentReadersAndWriter is the -race proof of the Registry's
// first synchronization: readers hammer Get/List (the external read surface —
// derivation, the chain, api handlers all read through these) while a writer
// loops SetBindingOptions and refreshes the cache under the same lock. Clean
// under -race means the Open-only-built maps are now properly guarded.
func TestRegistryConcurrentReadersAndWriter(t *testing.T) {
	ctx := context.Background()
	r, _ := openRegistry(t)

	const (
		iterations = 50
		readers    = 4
	)
	writerDone := make(chan struct{})
	var wg sync.WaitGroup
	errCh := make(chan error, 1)

	wg.Add(readers)
	for i := 0; i < readers; i++ {
		go func() {
			defer wg.Done()
			for {
				select {
				case <-writerDone:
					return
				default:
				}
				m, err := r.Get("tv")
				if err != nil {
					errCh <- fmt.Errorf("Get: %w", err)
					return
				}
				if len(m.MetadataSources) == 0 {
					errCh <- fmt.Errorf("Get returned an empty chain")
					return
				}
				if _, err := r.List(); err != nil {
					errCh <- fmt.Errorf("List: %w", err)
					return
				}
				if _, err := r.DisplayFields("tv", "tmdb"); err != nil {
					errCh <- fmt.Errorf("DisplayFields: %w", err)
					return
				}
			}
		}()
	}

	var lastOpts json.RawMessage
	go func() {
		defer close(writerDone)
		for i := 0; i < iterations; i++ {
			opts := json.RawMessage(fmt.Sprintf(`{"api_key":"k%d","language":"ru-RU"}`, i))
			if err := r.SetBindingOptions(ctx, "tv", "tmdb", opts); err != nil {
				errCh <- fmt.Errorf("SetBindingOptions iteration %d: %w", i, err)
				return
			}
			lastOpts = opts
		}
	}()
	<-writerDone
	wg.Wait()
	close(errCh)
	for err := range errCh {
		t.Fatalf("concurrent access: %v", err)
	}

	// The last write wins on both surfaces: the cache and the row.
	m, err := r.Get("tv")
	if err != nil {
		t.Fatalf("final Get: %v", err)
	}
	for _, src := range m.MetadataSources {
		if src.PluginID == "tmdb" && !bytes.Equal(src.Options, lastOpts) {
			t.Errorf("final cached options = %s, want %s", src.Options, lastOpts)
		}
	}
	if got := rowConfig(t, r, "tv"); !bytes.Contains([]byte(got), lastOpts) {
		t.Errorf("final row does not carry the last write %s", lastOpts)
	}
}
